import { useState, type FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

type RegistrationData = {
  fullName: string;
  email: string;
  street: string;
  city: string;
  postalCode: string;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

type RegistrationFormProps = {
  onSubmit: (data: RegistrationData) => void;
};

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    fullName: '',
    email: '',
    street: '',
    city: '',
    postalCode: '',
  });

  const emailError =
    step === 0 && data.email.length > 0 && !data.email.includes('@')
      ? 'Укажите адрес с символом @'
      : undefined;

  const isLastStep = step === STEPS.length - 1;

  const canGoNext =
    step === 0
      ? data.fullName.trim().length > 0 && data.email.includes('@')
      : step === 1
        ? data.street.trim().length > 0 && data.city.trim().length > 0
        : true;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLastStep) {
      onSubmit(data);
    } else if (canGoNext) {
      setStep((current) => Math.min(current + 1, STEPS.length - 1));
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 20px)', maxWidth: 420 }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 12px)' }}>
          <JxInputField
            label="Полное имя"
            required
            value={data.fullName}
            onChange={(event) => setData((prev) => ({ ...prev, fullName: event.target.value }))}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={(event) => setData((prev) => ({ ...prev, email: event.target.value }))}
            errorText={emailError}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 12px)' }}>
          <JxInputField
            label="Улица и дом"
            required
            value={data.street}
            onChange={(event) => setData((prev) => ({ ...prev, street: event.target.value }))}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={(event) => setData((prev) => ({ ...prev, city: event.target.value }))}
          />
          <JxInputField
            label="Почтовый индекс"
            value={data.postalCode}
            onChange={(event) => setData((prev) => ({ ...prev, postalCode: event.target.value }))}
            helperText="Необязательно"
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 8px)' }}>
          <p>
            <strong>Имя:</strong> {data.fullName || '—'}
          </p>
          <p>
            <strong>Email:</strong> {data.email || '—'}
          </p>
          <p>
            <strong>Адрес:</strong> {data.street || '—'}, {data.city || '—'}
            {data.postalCode ? `, ${data.postalCode}` : ''}
          </p>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-gap, 8px)' }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(current - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={!canGoNext}>
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

